import { createCipheriv, createDecipheriv, createHash, randomBytes } from 'node:crypto';

/**
 * Encrypts small secrets at rest (TOTP seeds in `app_user.totp_secret_enc`) with AES-256-GCM.
 * Key: SHA-256 of `HMIS_SECRET_KEY` (≥ 32 chars, generated by install.sh, never committed).
 * Format: `v1.<iv>.<tag>.<ciphertext>` (base64url).
 */

export class SecretKeyMissingError extends Error {
  constructor() {
    super('HMIS_SECRET_KEY is not set (or shorter than 32 characters)');
    this.name = 'SecretKeyMissingError';
  }
}

function key(env: NodeJS.ProcessEnv): Buffer {
  const raw = env.HMIS_SECRET_KEY;
  if (!raw || raw.length < 32) throw new SecretKeyMissingError();
  return createHash('sha256').update(raw, 'utf8').digest();
}

export const hasSecretKey = (env: NodeJS.ProcessEnv = process.env): boolean =>
  (env.HMIS_SECRET_KEY?.length ?? 0) >= 32;

export function sealSecret(plain: string, env: NodeJS.ProcessEnv = process.env): string {
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key(env), iv);
  const ct = Buffer.concat([cipher.update(plain, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return ['v1', iv, tag, ct]
    .map((p) => (typeof p === 'string' ? p : p.toString('base64url')))
    .join('.');
}

/** Throws on a wrong key or tampered value. */
export function openSecret(sealed: string, env: NodeJS.ProcessEnv = process.env): string {
  const [version, iv, tag, ct] = sealed.split('.');
  if (version !== 'v1' || !iv || !tag || ct === undefined) throw new Error('bad sealed secret');
  const decipher = createDecipheriv('aes-256-gcm', key(env), Buffer.from(iv, 'base64url'));
  decipher.setAuthTag(Buffer.from(tag, 'base64url'));
  return Buffer.concat([decipher.update(Buffer.from(ct, 'base64url')), decipher.final()]).toString(
    'utf8',
  );
}
